def _stance_block(ctx: Any) -> str:
    """她自己说过的立场。只给立场本身，不给原话上下文——避免变成复读。"""
    by = getattr(ctx, "stances", None) or {}
    if not isinstance(by, dict) or not by:
        return ""
    lines: list[str] = []
    # 亲口对用户说过的（say_*）
    for kind, label in (("boundary", "你划的线"), ("judgment", "你的判断"), ("preference", "你的偏好")):
        vals = [str(v).strip() for v in (by.get("say_" + kind) or []) if str(v).strip()]
        if vals:
            lines.append(f"· {label}：" + "；".join(vals))
    # 她心里想/读到想到的（无前缀）——确实是她的想法，但不是亲口说过的
    thought_vals = []
    for kind in ("boundary", "judgment", "preference"):
        for v in (by.get(kind) or []):
            v = str(v).strip()
            if v:
                thought_vals.append(v)
    if thought_vals:
        lines.append("· 你心里转过的想法（读到/想到，没亲口说过）：" + "；".join(thought_vals))
    if not lines:
        return ""
    return (
        "\n[你自己说过的话] 这些是你以前真说过的，现在还是你的看法，"
        "遇到相关的事就照这个来——不用重复原话，也不用主动汇报：\n"
        + "\n".join(lines)
    )


def _persona_first_contract_text(ctx: Any) -> str:
    """闲聊盘回应姿态合同：开关开时去掉配额式子句（句数、问号配额）。"""
    from agent.chat_tape_policy import trim_contract
    return trim_contract(_CHAT_TAPE_OUTPUT_CONTRACT, ctx)


def _persona_first_output_contract(contract: str, ctx: Any) -> str:
    """闲聊盘开关开时，去掉 _PERSONA_FIRST_OUTPUT_DROP 中的机器行与句数约束。

    逐段精确删除（不做宽泛正则）；非闲聊盘或开关关时原样返回。
    """
    from agent.chat_tape_policy import persona_first_keep
    if not persona_first_keep(ctx):
        return contract
    out = contract
    for piece in _PERSONA_FIRST_OUTPUT_DROP:
        out = out.replace(piece, "")
    return out


