    @staticmethod
    def _clean_material_external_context(value: Any) -> Dict[str, Any]:
        """Keep only short, safe, attributed search-result fields for prompts."""
        if not isinstance(value, dict) or str(value.get("status") or "") != "ready":
            return {}
        sources = []
        for item in (value.get("sources") or [])[:3]:
            if not isinstance(item, dict):
                continue
            url = " ".join(str(item.get("url") or "").split()).strip()
            if not re.match(r"^https?://[^\s]+$", url, re.IGNORECASE):
                continue
            sources.append({
                "title": " ".join(str(item.get("title") or "").split())[:180],
                "url": url[:500],
                "host": " ".join(str(item.get("host") or "").split())[:120],
                "snippet": " ".join(str(item.get("snippet") or "").split())[:420],
                "body_text": str(item.get("body_text") or "")[:24000],
                "body_url": str(item.get("body_url") or url)[:500],
                "evidence_kind": str(item.get("evidence_kind") or "web_excerpt")[:40],
                "retrieval_query": str(item.get("retrieval_query") or "")[:220],
            })
        queries = [" ".join(str(query or "").split())[:220]
                   for query in (value.get("queries") or [])[:2]
                   if len(str(query or "").strip()) >= 8]
        if not queries and value.get("query"):
            queries = [" ".join(str(value.get("query") or "").split())[:220]]
        return {"status": "ready", "sources": sources,
                "queries": queries} if sources else {}

    @staticmethod
    def _external_context_needed(query: str, external_context: Any = None) -> bool:
        text = " ".join(str(query or "").split()).casefold()
        if not text:
            return False
        if TutorAgent._material_user_asks_external_source(text):
            return True
        if re.search(
            r"(没玩过|没看过|不熟悉|不了解|背景|世界观|设定|这个游戏|这款游戏|"
            r"谁是|谁有|是什么|什么意思|怎么回事|前情|前面发生|讲一下.*游戏|"
            r"haven't\s+(?:played|seen|watched)|never\s+played|new\s+to(?:\s+the)?\b|"
            r"not\s+familiar\s+with|don't\s+know\s+much\s+about|unfamiliar|"
            r"background|lore|(?:world|game|story)\s+setting|who\s+(?:is|are)|"
            r"what\s+(?:is|are)|what\s+does\s+.+\s+mean|what's\s+going\s+on)",
            text, re.IGNORECASE,
        ):
            return True
        context = TutorAgent._clean_material_external_context(external_context)
        context_text = " ".join(
            "%s %s %s" % (item.get("title") or "", item.get("snippet") or "",
                            item.get("body_text") or "")
            for item in context.get("sources") or []
        ).casefold()
        context_search_terms = " ".join(context.get("queries") or []).casefold()
        stop_terms = {"the", "and", "for", "with", "that", "this", "what", "who",
                      "when", "where", "why", "how", "did", "does", "after", "before",
                      "from", "into", "about", "same", "have", "been", "were", "you"}
        from engine.material_analyzer import query_tokens
        query_terms = [token for token in query_tokens(text)
                       if len(token) >= 2 and token not in stop_terms]
        return bool(any(term in context_text or term in context_search_terms
                        for term in query_terms))

    @staticmethod
    def _material_user_asks_external_source(query: str) -> bool:
        return bool(re.search(
            r"(出处|来源|链接|哪一页|哪个网页|哪来的|从哪里查|给我.*(?:链接|来源)|"
            r"\b(?:source|citation|link|website|webpage|which page|where did you get)\b)",
            " ".join(str(query or "").split()), re.IGNORECASE,
        ))

    @staticmethod
    def _material_definition_concepts_missing(query: str, reply: str) -> List[str]:
        """Catch a material answer that never names the concept the user asked about."""
        query_text = " ".join(str(query or "").split())
        answer = str(reply or "")
        patterns = (
            r"(?i:\bwhat\s+are\s+(?:people\s+)?talking\s+about\s+when\s+(?:they|you)\s+mention\s+(?:the\s+)?)"
            r"([A-Z][A-Za-z0-9'-]+)\b",
            r"(?i:\bwhat\s+does\s+[A-Za-z][A-Za-z0-9'-]*\s+mean\s+by\s+(?:the\s+)?)"
            r"([A-Z][A-Za-z0-9'-]+)\b",
            r"(?i:\bwhat\s+does\s+)([A-Z][A-Za-z0-9'-]+)(?i:\s+mean)\b",
            r"(?i:\bwhat\s+(?:is|are)\s+(?:the\s+)?)"
            r"([A-Z][A-Za-z0-9'-]+)\b",
            r"(?i:\bis\s+that\s+(?:the\s+)?)"
            r"([A-Z][A-Za-z0-9'-]+)\b",
            r"(?:^|[?？。])\s*([A-Z][A-Za-z0-9'-]+)\s*(?:是什麼|是什么|指什麼|指什么|什么意思|是啥)",
        )
        concepts = []
        for pattern in patterns:
            concepts.extend(match.group(1) for match in re.finditer(pattern, query_text))
        missing = []
        for concept in dict.fromkeys(concepts):
            if concept.casefold() == "that":
                continue
            if concept.casefold().endswith("ing") and len(concept) > 5:
                stem = re.escape(concept[:-3])
                answer_has_concept = bool(re.search(
                    r"\b" + stem + r"(?:ing|ed|s)?\b", answer, re.IGNORECASE))
            else:
                answer_has_concept = bool(re.search(
                    r"\b" + re.escape(concept) + r"\b", answer, re.IGNORECASE))
            if not answer_has_concept:
                missing.append(concept)
        return missing[:3]

    @staticmethod
    def _material_relation_answer_is_confusing(query: str, reply: str) -> bool:
        """Catch one narrow failure: a pronoun-led claim links two terms, then denies it."""
        query_text = " ".join(str(query or "").split())
        answer = " ".join(str(reply or "").split())
        primary_match = re.search(
            r"\bwhat\s+does\s+[A-Za-z][A-Za-z0-9'-]*\s+mean\s+by\s+(?:the\s+)?"
            r"([A-Z][A-Za-z0-9'-]+)", query_text, re.IGNORECASE,
        )
        related_match = re.search(
            r"\b(?:is|are)\s+(?:it|that|this)\s+(?:the\s+)?"
            r"([A-Z][A-Za-z0-9'-]+)\b", query_text, re.IGNORECASE,
        )
        if not primary_match or not related_match:
            return False
        primary = primary_match.group(1)
        related = related_match.group(1)
        if primary.casefold() == related.casefold():
            return False
        sentences = [part.strip() for part in re.split(r"(?<=[.!?])\s+", answer) if part.strip()]
        if len(sentences) < 2:
            return False
        first = sentences[0]
        if re.search(r"\b" + re.escape(primary) + r"\b", first, re.IGNORECASE):
            return False
        if not re.match(r"(?i)^(?:it|that|this)\b", first):
            return False
        if not re.search(r"\b" + re.escape(related) + r"\b", first, re.IGNORECASE):
            return False
        later = " ".join(sentences[1:])
        denial = re.search(
            r"\b" + re.escape(primary) + r"\b.{0,45}\b"
            r"(?:isn't|is not|doesn't mean|does not mean|is separate from|is different from)\b"
            r".{0,25}\b" + re.escape(related) + r"\b|"
            r"\b" + re.escape(primary) + r"\b.{0,45}\bnot\s+(?:the\s+)?"
            r"" + re.escape(related) + r"\b",
            later, re.IGNORECASE,
        )
        return bool(denial)

    @staticmethod
    def _material_reply_repeats_adjacent_core(query: str, reply: str) -> bool:
        """Detect a repeated conclusion, including a quote that restates a yes/no answer."""
        if re.search(
            r"(?i:\b(?:quote|exact\s+words|word\s+for\s+word|verbatim)\b|"
            r"\bwhat\s+(?:did|does)\s+\w+\s+say\b|\bwhat\s+were\s+.+?\s+exact\s+words\b)|"
            r"原话|逐字|一字不差|具体怎么说",
            str(query or ""),
        ):
            return False
        parts = [part.strip() for part in re.split(r"(?<=[.!?。！？])\s+", str(reply or ""))
                 if part.strip()]
        sentences: List[str] = []
        for part in parts:
            if sentences and re.search(r"(?i)\b(?:dr|mr|mrs|ms|prof)\.$", sentences[-1]):
                sentences[-1] += " " + part
            else:
                sentences.append(part)
        token_re = re.compile(r"[a-z0-9]+(?:['’][a-z0-9]+)?|[\u4e00-\u9fff]", re.IGNORECASE)
        tokenized = [token_re.findall(sentence.casefold()) for sentence in sentences]
        min_run = 6
        for left, right in zip(tokenized, tokenized[1:]):
            if min(len(left), len(right)) < min_run:
                continue
            right_ngrams = {
                tuple(right[index:index + min_run])
                for index in range(len(right) - min_run + 1)
            }
            if any(tuple(left[index:index + min_run]) in right_ngrams
                   for index in range(len(left) - min_run + 1)):
                return True
        if (len(sentences) >= 2
                and re.match(r"(?i)^\s*(?:no\b|not\s+yet\b|not\s+really\b)", sentences[0])
                and re.search(r"(?i)\b(?:do|does|did|is|are|was|were|can|could|has|have|will|would)\b",
                              str(query or ""))):
            stop_words = {
                "so", "by", "the", "end", "of", "this", "part", "does", "do", "did",
                "is", "are", "was", "were", "can", "could", "has", "have", "will",
                "would", "should", "she", "he", "they", "we", "you", "i", "it", "a",
                "an", "to", "in", "on", "at", "yet", "how", "what", "who", "when",
                "where", "why", "not", "no",
            }
            query_terms = {
                token for token in re.findall(r"[a-z0-9]+", str(query or "").casefold())
                if len(token) > 1 and token not in stop_words
            }
            if len(query_terms) >= 2:
                for sentence in sentences[1:]:
                    sentence_terms = set(re.findall(r"[a-z0-9]+", sentence.casefold()))
                    repeats_polar_answer = bool(re.search(
                        r"(?i)\b(?:don't|do\s+not|doesn't|does\s+not|didn't|did\s+not|"
                        r"can't|cannot|isn't|is\s+not|aren't|are\s+not|hasn't|has\s+not|"
                        r"haven't|have\s+not|not\s+yet)\b", sentence,
                    ))
                    if repeats_polar_answer and query_terms.issubset(sentence_terms):
                        return True
                    for quoted in re.findall(r'[\"“]([^\"”]+)[\"”]', sentence):
                        quote_terms = set(re.findall(r"[a-z0-9]+", quoted.casefold()))
                        quote_repeats_polar_answer = bool(re.search(
                            r"(?i)\b(?:don't|do\s+not|doesn't|does\s+not|didn't|did\s+not|"
                            r"can't|cannot|isn't|is\s+not|aren't|are\s+not|hasn't|has\s+not|"
                            r"haven't|have\s+not|not\s+yet)\b", quoted,
                        ))
                        if (quote_repeats_polar_answer
                                and query_terms.issubset(quote_terms)):
                            return True
        if (len(sentences) >= 2
                and re.match(
                    r"(?i)^\s*(?:right\b|yes\b|exactly\b|correct\b|no\b|not\s+yet\b|"
                    r"not\s+really\b|that['’]s\s+right\b)", sentences[0],
                )):
            # A source-attributed paraphrase can repeat a user's confirmation
            # question without sharing six consecutive tokens. If both the
            # direct answer and an attributed follow-up make the same negative
            # claim about the same action, the first sentence already answered it.
            action_terms = {
                token for token in re.findall(r"[a-z0-9]+", str(query or "").casefold())
                if len(token) >= 4 and token not in {
                    "what", "when", "where", "which", "while", "does", "did", "have",
                    "been", "they", "them", "their", "this", "that", "with", "from",
                    "into", "about", "after", "before", "still", "just", "really",
                    "right", "then", "than", "were", "will", "would", "could", "should",
                    "know", "figure", "figured", "end", "part",
                }
            }
            first_terms = set(re.findall(r"[a-z0-9]+", sentences[0].casefold()))
            first_is_negative = bool(re.search(
                r"(?i)\b(?:don't|do\s+not|doesn't|does\s+not|didn't|did\s+not|"
                r"can't|cannot|isn't|is\s+not|aren't|are\s+not|hasn't|has\s+not|"
                r"haven't|have\s+not|not\s+yet|never)\b", sentences[0],
            ))
            if action_terms and first_is_negative:
                for sentence in sentences[1:]:
                    attributed = bool(re.search(
                        r"(?i)\b(?:[A-Z][a-z]+|he|she|they|the\s+speaker|the\s+narrator|"
                        r"the\s+creator|the\s+host)\s+(?:says|said|adds|added|explains|"
                        r"explained|tells|told)\b", sentence,
                    ))
                    sentence_terms = set(re.findall(r"[a-z0-9]+", sentence.casefold()))
                    negative = bool(re.search(
                        r"(?i)\b(?:don't|do\s+not|doesn't|does\s+not|didn't|did\s+not|"
                        r"can't|cannot|isn't|is\s+not|aren't|are\s+not|hasn't|has\s+not|"
                        r"haven't|have\s+not|not\s+yet|never)\b", sentence,
                    ))
                    if attributed and negative and action_terms.intersection(first_terms & sentence_terms):
                        return True
        return False

    @staticmethod
    def _material_trim_repeated_followup_sentence(query: str, reply: str) -> str:
        """Keep the direct answer when a following sentence repeats its core verbatim."""
        if not TutorAgent._material_reply_repeats_adjacent_core(query, reply):
            return str(reply or "").strip()
        sentences = [part.strip() for part in re.split(
            r"(?<=[.!?。！？])\s+", str(reply or "")
        ) if part.strip()]
        merged: List[str] = []
        for part in sentences:
            if merged and re.search(r"(?i)\b(?:dr|mr|mrs|ms|prof)\.$", merged[-1]):
                merged[-1] += " " + part
            else:
                merged.append(part)
        # This is a local last resort after the model and its one recovery attempt
        # both repeated themselves: the first sentence already answers the question.
        return merged[0] if merged else str(reply or "").strip()

    @classmethod
    def _material_cached_background(cls, sources: Sequence[Dict[str, Any]],
                                    query: str) -> str:
        """One bounded cached-background packet shared by both reply routes."""
        rows = []
        research_turn = bool(re.search(
            r"研究|证据|\b(?:research|studies|study|evidence|trial)\b", query, re.I))
        budget = 4800 if research_turn else 1050
        for source in sources:
            if not isinstance(source, dict) or budget <= 0:
                continue
            if not cls._external_context_needed(query, source.get("external_context")):
                continue
            rendered = cls._material_external_context_text(
                source.get("external_context"),
                source_title=str(source.get("title") or "素材"),
                budget=min(4800 if research_turn else 600, budget),
                include_source_details=cls._material_user_asks_external_source(query),
                query=query)
            if rendered:
                rows.append(rendered)
                budget -= len(rendered) + 1
        return ("\n".join(rows) + "\n" + cls._MATERIAL_EXTERNAL_BACKGROUND_RULE
                if rows else "")

    @classmethod
    def _material_external_context_text(cls, value: Any, *, source_title: str = "",
                                        budget: int = 780,
                                        include_source_details: bool = False,
                                        query: str = "") -> str:
        context = cls._clean_material_external_context(value)
        if not context or budget <= 0:
            return ""
        from engine.material_analyzer import select_external_reference_passages
        rows = []
        used = 0
        for item in select_external_reference_passages(context, query):
            snippet = item["quote"]
            research_abstract = item.get("evidence_kind") == "research_abstract"
            excerpt_limit = 2200 if research_abstract else 400
            if include_source_details:
                title = item.get("title") or item.get("host") or "网页结果"
                row = "- %s：%s%s" % (
                    title[:120], snippet[:excerpt_limit],
                    ("（来源：%s）" % str(item.get("body_url") or item["url"])[:220]) if item.get("url") else "",
                )
            else:
                row = "- %s" % snippet[:excerpt_limit]
            if research_abstract:
                row = "论文作者摘要（非全文；样本/对象/限制须保留，不推定普遍有效）：" + row
            if source_title and include_source_details:
                row = "- 《%s》背景：%s" % (source_title[:48], row[2:])
            if used + len(row) + 1 > budget:
                continue
            rows.append(row)
            used += len(row) + 1
            if len(rows) >= 2:
                break
        return "\n".join(rows)

    @classmethod
    def _material_analysis_text(cls, analysis: dict, budget: int = 0) -> str:
        """深析产物 → 一段注入文本；没有产物返回空串（零增量，语句逐字不变）。

        `budget` > 0 时**按在场字段均分**并逐字段裁条目，而不是整段截断：
        整段截断会把排在后面的"时间线 / 没讲清的"永远切掉，六字段实际只剩前三个
        ——那等于把"对素材的理解"砍掉一半。均分保证六个维度都露脸。
        """
        if not isinstance(analysis, dict) or not analysis:
            return ""
        from engine.material_analyzer import (format_voice_source,
                                              format_voice_source_span)

        present = []
        for field, label in cls._MATERIAL_DEEP_LABELS:
            raw_items = analysis.get(field) or []
            if field == "voice_sources":
                items = [format_voice_source(i) for i in raw_items if i]
            elif field == "voice_source_spans":
                items = [format_voice_source_span(i) for i in raw_items if i]
            else:
                items = [str(i).strip() for i in raw_items if str(i or "").strip()]
            if items:
                present.append((label, items))
        if not present:
            return ""
        # "这是分析不是原文"必须在场：素材带合同写明"素材里没有的事实不得编"，
        # 不点明来源的话，模型会把推断当事实讲给用户（等于用分析污染事实）。
        header = ("[Material·分析] 以下是你读这份素材后的**分析**（你的观点，"
                  "不是素材原文里的事实）：\n")
        tail = ("\n用它引发用户开口、展开讨论，**也可以直接把你的看法说出来**"
                "（用户要能感到你对这份素材有自己的想法，而不是一味顺着他说）；"
                "引用时要区分“素材里说的”与“你觉得的”，不得把分析说成素材里的原话。")
        if analysis.get("voice_source_spans"):
            tail += "\n" + cls._MATERIAL_SOURCE_ATTRIBUTION_RULE
        # 头尾是固定开销，不参与均分——否则它们会吃掉最后一个字段的额度
        room = (int(budget or 0) - len(header) - len(tail) - len(present) * 3)
        per_field = (room // len(present)) if room > 0 else 0
        lines = []
        for label, items in present:
            if per_field:
                kept, used = [], 0
                for item in items:
                    # 至少留一条：某字段一条都进不去，等于该维度不存在
                    if kept and used + len(item) + 1 > per_field:
                        break
                    kept.append(item)
                    used += len(item) + 1
                items = kept
            lines.append("%s：%s" % (label, "；".join(items)))
        return header + "\n".join(lines) + tail


    def _refresh_scene_world(self, ctx: SessionContext, text: str = "") -> None:
        """解析并写入场景世界锚（幂等、纯本地、零模型调用）。

        只在"已进入场景"之后生效：``ctx.scene_context_set`` 为假时直接返回，
        所以"我喜欢喝咖啡"这类提及不会被误判成入戏——那是 IntentRouter 的门
        该管的事，这里只负责"进去之后这是个什么样的世界"。
        """
        if not ctx.scene_context_set:
            return
        brief = ctx.scenario_brief or text or ""
        key = ctx.scene_world_key or scene_world.resolve(brief)
        if not key:
            return
        if key != ctx.scene_world_key:
            # 换了场景就重新判坐标，避免沿用上一个场景的流程
            ctx.scene_world_key = key
            ctx.scene_world_locale = scene_world.detect_locale(brief)
            ctx.scene_world_details = []
        elif not ctx.scene_world_locale:
            ctx.scene_world_locale = scene_world.detect_locale(brief)
        # 坐标允许在对话中被用户一句话改掉（"我其实是在美国"）
        hinted = scene_world.detect_locale(text, default="")
        if hinted and hinted != ctx.scene_world_locale:
            ctx.scene_world_locale = hinted
        # 已确认信息：代码确定性抽取，用来禁止"问已经答过的问题"
        recent_user = [
            str(item.get("content") or "")
            for item in (ctx.messages or [])[-8:]
            if str(item.get("role") or "") == "user"
        ]
        details = scene_world.extract_confirmed_details(recent_user)
        if details:
            merged = list(ctx.scene_world_details or [])
            for item in details:
                if item not in merged:
                    merged.append(item)
            ctx.scene_world_details = merged[-10:]

    @staticmethod
    def _clean_transcript(text: str) -> str:
        """清洗 ASR 原文，避免口头填充词和直接重复污染意图判定与指代解析。

        - 去掉独立成词的中文填充词（嗯/啊/呃/额/唉/哟）与英文 uh/um/hmm/er；
        - 折叠连续重复的短语（"why why why" → "why"，"you does you can you does
          you can" → "you does you can"），仅在紧邻重复且不跨标点时折叠。
        """
        if not text:
            return text or ""
        t = str(text)
        # 中文填充词（前后是标点/空白/句界才删，避免误伤“对啊”“是啊”）
        t = re.sub(
            r"(^|[，。！？、；：\s])(?:嗯+|啊+|呃+|额+|唉+|哟+)(?=[，。！？、；：\s]|$)",
            r"\1", t,
        )
        # 英文填充词（独立词）
        t = re.sub(r"\b(?:uh+|um+|hmm+|er|erm|mm|ah)\b", " ", t, flags=re.IGNORECASE)
        # 连续重复折叠：单词语单元至少重复 3 次才折叠（避免误伤 had had / very very
        # 等合法强调）；2-4 词的短语单元紧邻重复 2 次即折叠（ASR 常见的整段复读）。
        t = re.sub(
            r"(\b\w[\w']*)(?:\s+\1\b){2,}",
            r"\1", t, flags=re.IGNORECASE,
        )
        return " ".join(t.split())

    @staticmethod
    def _distill_preference(value: str) -> str:
        """从记忆原文中提取学习偏好子句，去掉场景具体物件与废话。

        例：“我明确记一下：是蓝牙耳机左边没声音，我想换货。以后我也还想再练
        售后沟通和过去式” → “以后我也还想再练售后沟通和过去式”。
        """
        text = " ".join(str(value or "").split())
        if not text:
            return ""
        marker_match = re.search(
            r"(以后|下次|接下来|想练|多练|要练|重点练|希望练|喜欢学|更想练)[^。！？]*",
            text,
        )
        if marker_match and len(marker_match.group(0).strip()) >= 4:
            return marker_match.group(0).strip()[:60]
        first = re.split(r"[。；]", text, maxsplit=1)[0]
        first = re.sub(r"^(我)?(?:明确)?(?:记一下|记住)?[:：]?\s*", "", first)
        return first.strip()[:60]

    @staticmethod
    def _distill_weakness(value: str) -> str:
        """只保留真正的薄弱点表述；无法确认时返回空（不注入垃圾）。

        例：“你并不会继续推进这个事情”不含薄弱点语义 → 返回空。
        """
        text = " ".join(str(value or "").split())
        if not text:
            return ""
        if not re.search(
            r"(薄弱|不擅长|英语.{0,4}(不好|差)|口语.{0,4}(不好|差)|语法.{0,4}(不好|不会)|"
            r"发音.{0,4}(不好|不准)|过去式|过去时|时态|struggle|weak\s+(at|in)|"
            r"容易说错|老是说错|总说错|经常说错)",
            text, re.IGNORECASE,
        ):
            return ""
        clause = re.search(
            r"((?:英语|口语|语法|发音|时态|过去式)?[^。！？]{0,20}"
            r"(?:薄弱|不好|不擅长|不会说|说错|struggle|weak|差)[^。！？]{0,24})",
            text, re.IGNORECASE,
        )
        return (clause.group(1) if clause else text)[:60].strip()

    # 表达习惯标签 → 给模型的说明（plans/0919-03 §4.6）。
    # 键必须与 profile_evolution._distill_communication_style 产出的维度名一致；
    # 认不出的标签一律不注入。措辞只描述"怎么说"，不描述"是什么样的人"——
    # 后者属不可塑层（框架档 0919-01 §4.1），模型不得据此改写观点与边界。
    _COMM_STYLE_HINTS = {
        "direct": ("说话简短直接、不爱铺垫", "回复也短，少客套、不绕弯"),
        "expressive": ("情绪外露、爱用强化词和感叹", "可以接住他的情绪热度，语气别太平"),
        "analytical": ("讲事情带因果和条件、倾向把话说完", "给结构化解释，把因果讲清楚"),
        "hesitant": ("常带犹豫词、语气不确定", "多给确认与安全感，不催、不替他下结论"),
    }

    @classmethod
    def _render_communication_style(cls, ctx) -> list:
        """把 L1 表达习惯标签渲染成 prompt 段；无标签或标签不认时不注入。"""
        raw = str((ctx.profile or {}).get("communication_style") or "").strip()
        if not raw:
            return []
        labels = [part for part in raw.split("+") if part in cls._COMM_STYLE_HINTS]
        if not labels:
            return []
        traits = "；".join(cls._COMM_STYLE_HINTS[label][0] for label in labels)
        adapts = "；".join(cls._COMM_STYLE_HINTS[label][1] for label in labels)
        return [
            "[User Communication Style]（跨会话的长期表达习惯）",
            f"他说话的长期习惯：{traits}。",
            f"据此调整你的表达方式：{adapts}。",
            "这只调整「你怎么说」——不得据此推断他的性格、观点或立场，"
            "也不改变你自己的观点、边界与教学原则。",
            "",
        ]

    # 词义提问里的功能词与超高频词，不作为"可能被听错的实词"。
    _ASKED_WORD_STOPWORDS = {
        "the", "your", "you", "this", "that", "these", "those", "its", "their",
        "me", "my", "mine", "his", "her", "our", "and", "but", "for", "with",
        "from", "about", "into", "over", "under", "here", "there", "please",
        "thank", "thanks", "yes", "now", "then", "again", "more", "most",
        "some", "any", "name", "time", "way", "thing", "word", "words", "mean",
    }

    @staticmethod
    def _phonetic_key(token: str) -> str:
        """粗糙的发音骨架，只用来判断两个词听起来是否接近。

        不追求音标级准确：真正的模糊判断交给模型，这里只负责挑出明显
        同源的词（syrup/Siri、foam/phones 这类 ASR 误听）。
        """
        text = re.sub(r"[^a-z]", "", str(token or "").lower())
        text = (
            text.replace("ph", "f").replace("ck", "k").replace("c", "k")
            .replace("q", "k").replace("x", "ks").replace("z", "s")
            .replace("v", "f").replace("w", "v").replace("y", "i")
            # 鼻音合流：m/n 在听感上极易互换（foam 被听成 phones 就是这一类）。
            .replace("ng", "n").replace("m", "n")
        )
        return re.sub(r"[aeiou]", "", text)

    @staticmethod
    def _lcs_ratio(left: str, right: str) -> float:
        if not left or not right:
            return 0.0
        previous = [0] * (len(right) + 1)
        for lchar in left:
            current = [0]
            for index, rchar in enumerate(right):
                current.append(
                    previous[index] + 1 if lchar == rchar
                    else max(current[index], previous[index + 1])
                )
            previous = current
        return previous[-1] / max(len(left), len(right))

    @classmethod
    def _asked_word_tokens(cls, text: str) -> List[str]:
        """从"某个词什么意思"这类提问里抽出被问的词。"""
        found: List[str] = []

        def collect(phrase: str) -> None:
            for raw in re.findall(r"[A-Za-z][A-Za-z'\-]{0,24}", str(phrase or "")):
                # 只考虑纯字母单词：带连字符/撇号的（check-in、don't）通常是学习
                # 者自己就会用的真词，不该被当成误听。实测 "check-in" 会以 0.75
                # 的相似度撞上上一轮的 "choice"。
                if not raw.isalpha() or len(raw) > 15:
                    continue
                token = raw.lower()
                if len(token) < 3 or token in cls._ASKED_WORD_STOPWORDS:
                    continue
                if token not in found:
                    found.append(token)

        for match in re.finditer(r"what\s+(?:does|do)\s+(.+?)\s+mean", text, re.IGNORECASE):
            collect(match.group(1))
        for match in re.finditer(
            r"what(?:'s|\s+is|\s+are)\s+(.+?)(?:[.!?]|$)", text, re.IGNORECASE
        ):
            collect(match.group(1))
        for match in re.finditer(
            r"([A-Za-z][A-Za-z'\- ]{0,30}?)\s*(?:是什么意思|什么意思|啥意思|怎么读)", text
        ):
            collect(match.group(1))
        for match in re.finditer(r"['\"]([A-Za-z][A-Za-z'\-]{0,24})['\"]", text):
            collect(match.group(1))
        return found

    @classmethod
    def _asked_word_resolution(
        cls, user_text: str, messages: List[Dict[str, Any]]
    ) -> Dict[str, Any] | None:
        """学习者问"某个词什么意思"时，判断 ta 问的多半就是 AI 上一轮用过的词。

        ASR 会把生词听成熟词：实测学习者问 "What are syrup and foam?" 被转成
        "What are Siri and phones?"，模型于是认真解释了 Siri（苹果语音助手）——
        答非所问，看着还很蠢。AI 自己刚说过的词是最强的纠错锚点：只在这些词里
        找发音相近的候选，找到就把候选一并交给模型，让模型按那个词讲词义。
        """
        text = str(user_text or "").strip()
        if not text:
            return None
        asked = cls._asked_word_tokens(text)
        if not asked:
            return None

        last_assistant = ""
        for message in reversed(list(messages or [])):
            if (message.get("role") == "assistant"
                    and str(message.get("content") or "").strip()):
                last_assistant = str(message.get("content") or "")
                break
        if not last_assistant:
            return None

        tutor_words: List[str] = []
        for raw in re.findall(r"[A-Za-z][A-Za-z'\-]{2,}", last_assistant):
            token = raw.lower().strip("'-")
            if (len(token) >= 3 and token not in cls._ASKED_WORD_STOPWORDS
                    and token not in tutor_words):
                tutor_words.append(token)
        if not tutor_words:
            return None

        lowered = last_assistant.lower()
        unheard = [
            token for token in asked
            if not re.search(r"\b" + re.escape(token) + r"\b", lowered)
        ]
        # 被问的词确实出现在上一轮里 → 听对了，不需要纠。
        if not unheard:
            return None

        best: tuple[float, str, str] | None = None
        for token in unheard:
            key = cls._phonetic_key(token)
            if len(key) < 2:
                continue
            for word in tutor_words:
                word_key = cls._phonetic_key(word)
                if len(word_key) < 2 or word_key[0] != key[0]:
                    continue
                ratio = cls._lcs_ratio(key, word_key)
                if ratio >= 0.5 and (best is None or ratio > best[0]):
                    best = (ratio, token, word)
        if best is None:
            return None
        return {
            "asked_tokens": unheard,
            "likely_heard_as": best[1],
            "tutor_word": best[2],
            "tutor_recent_words": tutor_words[:12],
            "similarity": round(best[0], 3),
        }

    @staticmethod
    def _extract_deictic_candidate(assistant_text: str) -> str:
        """从上一轮AI回复中提取最可能的“指代对象”（作品/实体名）。

        优先级：《书名号》 → *斜体* → 引号 → 连续大写英文专有名词。
        用于用户问“这个电影名的中文翻译/介绍一下”时的确定性指代约束。
        """
        text = str(assistant_text or "")
        for pattern in (
            r"《([^》]{1,40})》",
            r"\*([^*]{1,60})\*",
            r'"([^"]{1,60})"',
            r"([A-Z][A-Za-z' ]{1,40}?)(?=[,。；、！？?\n]|$)",
        ):
            match = re.search(pattern, text)
            if match:
                candidate = " ".join(match.group(1).split()).strip()
                if candidate:
                    return candidate[:60]
        return ""

    def _rehydrate_scene_state(
        self, ctx: SessionContext, history: List[Dict[str, Any]]
    ) -> None:
        """Recover only the open scene contract after a proxy reconnect."""
        if ctx.learning_state is not None and ctx.learning_state.roleplay_active:
            ctx.active_scene = ctx.learning_state.scenario
            ctx.scenario_brief = ctx.learning_state.scenario_brief
            ctx.scenario_role = ctx.learning_state.tutor_role
            ctx.learner_role = ctx.learning_state.learner_role
            ctx.scenario_step = ctx.learning_state.scenario_step or "active_exchange"
            ctx.roleplay_turn = ctx.learning_state.roleplay_turn
            ctx.scene_context_set = bool(ctx.active_scene)
            self._refresh_scene_world(ctx)
            return

        user_messages = [
            str(item.get("content") or item.get("text") or "").strip()
            for item in (history or [])[-20:]
            if str(item.get("role") or "") == "user"
        ]
        scene_info = next(
            (info for content in reversed(user_messages) if (info := self._extract_scene_info(content))),
            None,
        )
        if scene_info is None:
            return
        ctx.active_scene = scene_info["scene"]
        ctx.scenario_brief = scene_info["brief"]
        ctx.scenario_role = scene_info["role"]
        ctx.learner_role = scene_info["learner_role"]
        ctx.scenario_step = "active_exchange"
        ctx.roleplay_turn = max(0, len(user_messages) - 1)
        ctx.target_goal = scene_info["goal"]
        ctx.scene_context_set = True
        if ctx.learning_state is not None:
            ctx.learning_state.stage = "flow"
            ctx.learning_state.scenario = ctx.active_scene
            ctx.learning_state.scenario_brief = ctx.scenario_brief
            ctx.learning_state.tutor_role = ctx.scenario_role
            ctx.learning_state.learner_role = ctx.learner_role
            ctx.learning_state.scenario_step = "active_exchange"
            ctx.learning_state.roleplay_turn = ctx.roleplay_turn
            ctx.learning_state.roleplay_active = True
        self._refresh_scene_world(ctx)

    @staticmethod
    def _rehydrate_turn_state(
        ctx: SessionContext, history: List[Dict[str, Any]]
    ) -> None:
        """Recover the latest interaction frame after a voice reconnect.

        Scene restoration answers where the conversation is.  This restores
        what kind of exchange was happening, so a short follow-up such as
        ``对吧？`` continues a lexical/pronunciation sidecar instead of being
        routed from an unrelated durable scene plan.
        """
        user_turns = [
            " ".join(str(item.get("content") or item.get("text") or "").split())
            for item in (history or [])[-20:]
            if str(item.get("role") or "") == "user"
            and str(item.get("content") or item.get("text") or "").strip()
        ]
        if not user_turns:
            return
        latest = user_turns[-1]
        prior = user_turns[-2] if len(user_turns) > 1 else ""
        previous_decision: Dict[str, Any] = {}
        if (
            len(latest) <= 70
            and TurnController.SIDECAR_FOLLOWUP.search(latest)
            and TurnController.LANGUAGE_QUERY.search(prior)
        ):
            previous_decision = {"primary_frame": "language_sidecar"}
        if not (
            TurnController.LANGUAGE_QUERY.search(latest)
            or TurnController.PROCESS_FEEDBACK.search(latest)
            or previous_decision
        ):
            return
        intent = (
            "method_negotiation"
            if TurnController.PROCESS_FEEDBACK.search(latest)
            else "lexical_clarification"
        )
        ctx.turn_decision = TurnController.decide(
            user_text=latest,
            communicative_intent=intent,
            scene_active=bool(ctx.scene_context_set),
            scene_changed=False,
            existing_plan=ctx.conversation_plan,
            previous_decision=previous_decision,
            previous_frame="",
        ).to_dict()

    @staticmethod
    def _infer_handover_item(
        user_text: str, prior_messages: List[Dict[str, Any]]
    ) -> str:
        """Infer the referenced artifact in a generic hand-over turn.

        This is deliberately scene-agnostic.  It resolves short utterances such
        as "OK, here" against the counterpart's immediately preceding request,
        instead of teaching the backend a catalogue of airport/hotel scripts.
        """
        text = " ".join(str(user_text or "").split())
        lower = text.lower()
        handover = bool(re.search(
            r"(给你|交给你|递给你|拿给你|给您|交给您|递给您|你自己看|"
            r"\bhere\s+you\s+are\b|(?:\bok[,， ]*)?\bhere\b)",
            lower,
            re.IGNORECASE,
        ))
        if not handover:
            return ""

        explicit_patterns = (
            r"(?:把|将)(.{1,28}?)(?:给你|交给你|递给你|拿给你|给您|交给您|递给您)",
            r"((?:这|那)(?:张|个|份|本)?[^，。,.!?]{0,18}(?:牌|票|卡|证|单|表|护照|手机|文件))",
            r"([^，。,.!?]{0,16}(?:行李牌|机票|登机牌|护照|证件|票据|表格|文件))",
        )
        for pattern in explicit_patterns:
            match = re.search(pattern, text, re.IGNORECASE)
            if match:
                item = " ".join(match.group(1).split()).strip("这个这张一份的 ")
                if item:
                    return item[:48]

        previous_assistant = next((
            " ".join(str(item.get("content") or item.get("text") or "").split())
            for item in reversed(prior_messages or [])
            if item.get("role") == "assistant"
        ), "")
        for pattern in (
            r"请把(.{1,36}?)(?:给我|交给我|递给我|拿给我|展示给我|出示给我)",
            r"(?:show|give|hand)\s+me\s+(?:the\s+)?([^.,!?]{1,28})",
        ):
            match = re.search(pattern, previous_assistant, re.IGNORECASE)
            if match:
                item = " ".join(match.group(1).split()).strip("这个这张一份的 ")
                if item:
                    return item[:48]
        return "所指材料"

    @staticmethod
    def _merge_ledger_list(
        existing: Any, incoming: Any, *, limit: int
    ) -> List[str]:
        values: List[str] = []
        for raw in list(existing or []) + list(incoming or []):
            value = " ".join(str(raw or "").split())[:160]
            if value and value not in values:
                values.append(value)
        return values[-limit:]

    def _update_scene_ledger(
        self, ctx: SessionContext, user_text: str, plan: Dict[str, Any]
    ) -> None:
        """Merge the model plan into an inspectable, irreversible episode ledger."""
        ledger = dict(ctx.scene_ledger or {})
        plan = plan or {}
        ledger["known_facts"] = self._merge_ledger_list(
            ledger.get("known_facts"), plan.get("known_facts"), limit=16
        )
        ledger["completed_actions"] = self._merge_ledger_list(
            ledger.get("completed_actions"), plan.get("completed_actions"), limit=16
        )
        ledger["available_items"] = self._merge_ledger_list(
            ledger.get("available_items"), plan.get("available_items"), limit=10
        )
        ledger["open_items"] = self._merge_ledger_list(
            [], plan.get("open_items"), limit=10
        )

        provided_slots = dict(ledger.get("provided_slots") or {})
        provided_slots.update(self._extract_provided_slots(user_text, ctx.messages))
        ledger["provided_slots"] = provided_slots
        guest_name = str(provided_slots.get("guest_name") or "")
        if guest_name:
            tokens = self._name_tokens(guest_name)
            ledger["name_address_count"] = sum(
                1 for message in ctx.messages
                if message.get("role") == "assistant"
                and any(
                    re.search(r"\b" + re.escape(token) + r"\b", str(message.get("content") or ""), re.IGNORECASE)
                    for token in tokens if re.search(r"[A-Za-z]", token)
                )
            )

        handed_item = self._infer_handover_item(user_text, ctx.messages)
        if handed_item:
            fact = f"学习者已把{handed_item}交给或展示给对方角色"
            ledger["known_facts"] = self._merge_ledger_list(
                ledger.get("known_facts"), [fact], limit=16
            )
            ledger["completed_actions"] = self._merge_ledger_list(
                ledger.get("completed_actions"), [fact], limit=16
            )
            ledger["available_items"] = self._merge_ledger_list(
                ledger.get("available_items"), [handed_item], limit=10
            )

        phase = str(plan.get("current_phase") or ctx.scenario_step or "").strip()
        if phase:
            phase = phase[:100]
            phase_history = self._merge_ledger_list(
                ledger.get("phase_history"), [phase], limit=12
            )
            previous_phase = str(ledger.get("current_phase") or "")
            is_old_phase = bool(
                previous_phase and phase != previous_phase
                and phase in list(ledger.get("phase_history") or [])[:-1]
            )
            if is_old_phase:
                ledger["blocked_regressions"] = self._merge_ledger_list(
                    ledger.get("blocked_regressions"),
                    [f"blocked phase rollback: {previous_phase} -> {phase}"],
                    limit=8,
                )
                plan["current_phase"] = previous_phase
                if ledger.get("next_counterpart_action"):
                    plan["next_counterpart_action"] = ledger["next_counterpart_action"]
            else:
                ledger["current_phase"] = phase
                ledger["phase_history"] = phase_history
        location = str(plan.get("current_location") or "").strip()[:120]
        if location:
            previous_location = str(ledger.get("current_location") or "")
            prior_locations = list(ledger.get("location_history") or [])
            is_old_location = bool(
                previous_location and location != previous_location
                and location in prior_locations[:-1]
            )
            if is_old_location:
                ledger["blocked_regressions"] = self._merge_ledger_list(
                    ledger.get("blocked_regressions"),
                    [f"blocked location rollback: {previous_location} -> {location}"],
                    limit=8,
                )
                plan["current_location"] = previous_location
                if ledger.get("next_counterpart_action"):
                    plan["next_counterpart_action"] = ledger["next_counterpart_action"]
            else:
                ledger["current_location"] = location
                ledger["location_history"] = self._merge_ledger_list(
                    prior_locations, [location], limit=12
                )
        next_action = str(plan.get("next_counterpart_action") or "").strip()
        if next_action:
            ledger["next_counterpart_action"] = next_action[:180]
        if user_text.strip():
            ledger["latest_user_input"] = " ".join(user_text.split())[:240]
            if not _PROMPT_CACHE_ORDER:
                # 缓存序下不再把每轮原话塞进 known_facts：满 16 条后 _merge 的
                # 头部淘汰会让权威 JSON 每轮分叉（plans/0916-10 续）。信息由
                # latest_user_input 与会话事实卡覆盖，[Reality] 的"本会话已确认
                # 事实"条款不受影响。
                ledger["known_facts"] = self._merge_ledger_list(
                    ledger.get("known_facts"),
                    ["学习者本轮明确说：" + " ".join(user_text.split())[:140]],
                    limit=16,
                )
        ctx.scene_ledger = ledger

    def _rehydrate_scene_ledger(
        self, ctx: SessionContext, history: List[Dict[str, Any]]
    ) -> None:
        """Recover irreversible hand-over events after a voice socket restart."""
        if ctx.scene_ledger:
            return
        ledger: Dict[str, Any] = {}
        prior: List[Dict[str, Any]] = []
        for item in (history or [])[-20:]:
            role = str(item.get("role") or "")
            content = str(item.get("content") or item.get("text") or "").strip()
            if role == "user" and content:
                provided_slots = dict(ledger.get("provided_slots") or {})
                provided_slots.update(self._extract_provided_slots(content, prior))
                ledger["provided_slots"] = provided_slots
                if not _PROMPT_CACHE_ORDER:
                    # 与 _update_scene_ledger 同口径：缓存序下不把原话写进
                    # known_facts（plans/0916-10 续）。
                    ledger["known_facts"] = self._merge_ledger_list(
                        ledger.get("known_facts"),
                        ["学习者本轮明确说：" + " ".join(content.split())[:140]],
                        limit=16,
                    )
                handed_item = self._infer_handover_item(content, prior)
                if handed_item:
                    fact = f"学习者已把{handed_item}交给或展示给对方角色"
                    ledger["known_facts"] = self._merge_ledger_list(
                        ledger.get("known_facts"), [fact], limit=16
                    )
                    ledger["completed_actions"] = self._merge_ledger_list(
                        ledger.get("completed_actions"), [fact], limit=16
                    )
                    ledger["available_items"] = self._merge_ledger_list(
                        ledger.get("available_items"), [handed_item], limit=10
                    )
            if role in {"user", "assistant"} and content:
                prior.append({"role": role, "content": content})
        ctx.scene_ledger = ledger
